import {
    computed,
    effect,
    inject,
    Injectable,
    OnDestroy,
    resource,
    signal,
    untracked,
    WritableSignal,
} from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { ViewAction, ViewerFeature } from '@placeos/common';
import { getModule, showMetadata } from '@placeos/ts-client';

import {
    AsyncHandler,
    BookingRuleset,
    CalendarEvent,
    currentUser,
    HashMap,
    i18n,
    isWithinBookableHours,
    OrganisationService,
    rulesForResource,
    SettingsService,
    Space,
} from '@placeos/common';
import { notifyError } from 'libs/common/src/lib/notifications';
import { EventFormService } from 'libs/events/src/lib/event-form.service';

import { ExploreBookQrComponent } from './explore-book-qr.component';
import { ExploreBookingModalComponent } from './explore-booking-modal.component';
import { loadBookingRules } from './explore-booking-rules';
import { ExploreIconComponent } from './explore-icon.component';
import {
    ExploreSpaceInfoComponent,
    SpaceInfoStatus,
} from './explore-space-info.component';
import { ExploreStateService } from './explore-state.service';

/** Live tooltip values for one space */
interface SpaceInfoSignals {
    space: WritableSignal<Space>;
    events: WritableSignal<CalendarEvent[]>;
    status: WritableSignal<SpaceInfoStatus>;
}

export const DEFAULT_COLOURS = {
    free: '#43a047',
    pending: '#ffb300',
    reserved: '#e65100',
    busy: '#e53935',
    'signs-of-life': '#1565c0',
    'not-bookable': '#757575',
    unknown: '#757575',
};

@Injectable()
export class ExploreSpacesService extends AsyncHandler implements OnDestroy {
    private _state = inject(ExploreStateService);
    private _settings = inject(SettingsService);
    private _event_form = inject(EventFormService);
    private _dialog = inject(MatDialog);
    private _org = inject(OrganisationService);

    private _building = this._org.active_building;

    /** Tooltip values by space ID. Map features share these signals */
    private _space_info: Record<string, SpaceInfoSignals> = {};
    private _statuses: Record<string, string> = {};
    private _presence: Record<string, boolean> = {};
    private _panning = true;
    private _last_action = '';

    private _booking_rules = resource({
        params: () => this._building() || undefined,
        loader: ({ params: bld }) => loadBookingRules(bld.id, 'room'),
    });
    public readonly booking_rules = computed<BookingRuleset[]>(
        () => this._booking_rules.value() ?? [],
    );

    private _room_alerts = resource({
        params: () => this._building() || undefined,
        loader: () =>
            showMetadata(this._org.organisation.id, `room_alerts`)
                .then((_) => _.details || {})
                .catch(() => ({})),
    });
    public readonly room_alerts = computed<HashMap>(
        () => this._room_alerts.value() ?? {},
    );

    constructor() {
        super();
        effect(() => {
            const list = this._state.spaces();
            const { is_public } = this._state.options();
            if (is_public) return;
            untracked(() => this._bindToSpaces(list));
        });
    }

    private _bindToSpaces(list: Space[]) {
        this.unsubWith('b-');
        this.unsubWith('s-');
        this.unsubWith('c-');
        this._statuses = {};
        const previous_info = this._space_info;
        this._space_info = {};
        for (const space of list || []) {
            const info = previous_info[space.id] || {
                space: signal(new Space(space)),
                events: signal<CalendarEvent[]>([]),
                status: signal<SpaceInfoStatus>('not-bookable'),
            };
            info.space.set(new Space(space));
            info.status.set('not-bookable');
            this._space_info[space.id] = info;
        }
        if (!list?.length) return;
        for (const space of list) {
            const mod = getModule(space.id, 'Bookings');
            let binding = mod.variable('bookings');
            this.subscription(
                `b-${space.id}`,
                binding.bindThenSubscribe((d) =>
                    this.handleBookingsChange(space, d),
                ),
            );
            binding = mod.variable('status');
            this.subscription(
                `s-${space.id}`,
                binding.bindThenSubscribe((d) =>
                    this.handleStatusChange(list, space, d),
                ),
            );
            binding = mod.variable('presence');
            this.subscription(
                `c-${space.id}`,
                binding.bindThenSubscribe((d) =>
                    this.handlePresenceChange(list, space, d),
                ),
            );
        }
        this.updateActions(list);
        this._updateHoverElements(list);
    }

    public async bookSpace(space: Space, force = false) {
        if (this._panning && this._last_action === 'down') return;
        const booking_rules = this.booking_rules();
        const room_alerts = this.room_alerts();
        const { hidden } =
            rulesForResource(
                {
                    date: Date.now(),
                    duration: 60,
                    resource: space,
                    host: currentUser(),
                },
                booking_rules,
            ) || {};
        if (hidden) {
            return notifyError(i18n('EXPLORE.SPACES_PERMISSIONS_ERROR'));
        }
        if (
            (this._statuses[space.id] !== 'free' && !force) ||
            !space.bookable
        ) {
            return notifyError(
                i18n('EXPLORE.SPACES_UNAVAILABLE_ERROR', {
                    name: space.display_name || space.name,
                }),
            );
        }
        if (room_alerts[space.id]?.[0] === 'closed') {
            return notifyError(`${room_alerts[space.id][1]}`);
        }
        const bookable_hours = this._settings.get('app.events.bookable_hours');
        if (
            bookable_hours &&
            !isWithinBookableHours(Date.now(), bookable_hours)
        ) {
            return notifyError(i18n('EXPLORE.OUTSIDE_BOOKABLE_HOURS'));
        }
        if (this._settings.get('app.events.booking_unavailable')) {
            return this._event_form.openEventLinkModal();
        }
        if (space.room_booking_url) {
            const [email_start, email_end] = space.email.split('@');
            const url = space.room_booking_url
                .replace(/\{id\}/g, encodeURIComponent(space.id))
                .replace(
                    /\{name\}/g,
                    encodeURIComponent(space.display_name || space.name),
                )
                .replace(/\{map_id\}/g, encodeURIComponent(space.map_id))
                .replace(/\{email\}/g, encodeURIComponent(space.email))
                .replace(
                    /\{email_start\}/g,
                    encodeURIComponent(email_start || ''),
                )
                .replace(/\{email_end\}/g, encodeURIComponent(email_end || ''));
            window.open(url, '_blank', 'noopener noreferer');
            return;
        }
        this._event_form.newForm();
        this._event_form.model.update((m) => ({
            ...m,
            host: currentUser()?.email,
            resources: [space],
        }));
        this._dialog.open(
            (this._settings.get('app.explore.show_booking_qr')
                ? ExploreBookQrComponent
                : ExploreBookingModalComponent) as any,
            {
                data: { space, alert: room_alerts[space.id] },
            },
        );
    }

    public handleBookingsChange(space: Space, bookings: HashMap[]) {
        if (!bookings) return;
        this._space_info[space.id]?.events.set(
            bookings.map((i) => new CalendarEvent(i)),
        );
    }

    public handleStatusChange(spaces: Space[], space: Space, status: string) {
        if (space.bookable) this._statuses[space.id] = status || 'free';
        else delete this._statuses[space.id];
        this._space_info[space.id]?.status.set(
            (this._statuses[space.id] || 'not-bookable') as SpaceInfoStatus,
        );
        this.timeout('update_statuses', () => this._updateStatus(spaces), 100);
    }

    public handlePresenceChange(
        spaces: Space[],
        space: Space,
        presence: boolean,
    ) {
        this._presence[space.id] = presence;
        this.timeout('update_icons', () => this._updateIcons(spaces), 100);
    }

    private async _updateStatus(spaces: Space[]) {
        const style_map = {};
        const colours = this._settings.get('app.explore.colors') || {};
        for (const space of spaces) {
            if (!this._statuses[space.id]) continue;
            const status = this._statuses[space.id];
            style_map[`#${space.map_id}`] = {
                fill:
                    colours[`space-${status}`] ||
                    colours[`${status}`] ||
                    DEFAULT_COLOURS[`${status}`],
                opacity: 0.6,
            };
        }
        this._state.setStyles('spaces', style_map);
    }

    /**
     * Set the tooltip features for the spaces. The stable track ID and
     * signal data let the map keep each tooltip component when other
     * features change.
     */
    private _updateHoverElements(spaces: Space[]) {
        const features: ViewerFeature[] = [];
        for (const space of spaces) {
            const info = this._space_info[space.id];
            if (!space.map_id || !info) continue;
            features.push({
                track_id: `space:hover:${space.id}`,
                location: space.map_id,
                full_size: true,
                no_scale: true,
                content: ExploreSpaceInfoComponent,
                z_index: 10,
                data: { ...info },
            } as ViewerFeature);
        }
        this._state.setFeatures('spaces', features);
    }

    private _updateIcons(spaces: Space[]) {
        if (!this._settings.get('app.show_presence_indicators')) return;
        const features: ViewerFeature[] = [];
        for (const space of spaces) {
            if (!space.map_id) continue;
            features.push({
                location: space.map_id,
                content: ExploreIconComponent,
                data: {
                    icon: {
                        class: 'material-symbols-rounded',
                        content: 'sensor_occupied',
                    },
                    color: this._presence[space.id]
                        ? 'var(--success)'
                        : 'var(--base-content)',
                    text_color: this._presence[space.id]
                        ? 'var(--success-content)'
                        : 'var(--base-100)',
                },
                z_index: 98,
            } as ViewerFeature);
        }
        this._state.setFeatures('spaces-presence', features);
    }

    private updateActions(spaces: Space[]) {
        const actions: ViewAction[] = [];
        for (const space of spaces) {
            if (!space.map_id) continue;
            for (const action of ['mousedown', 'touchstart']) {
                actions.push({
                    id: space.map_id,
                    action: action,
                    priority: 5,
                    callback: () => {
                        this._panning = false;
                        this.timeout(
                            'panning',
                            () => (this._panning = true),
                            300,
                        );
                        this._last_action = 'down';
                    },
                });
            }
            for (const action of ['mouseup', 'touchend']) {
                actions.push({
                    id: space.map_id,
                    action: action,
                    priority: 5,
                    callback: () => {
                        this.bookSpace(space);
                        this._last_action = 'up';
                    },
                });
            }
        }

        this.timeout(
            'set-actions',
            () => this._state.setActions('spaces', actions),
            50,
        );
    }
}
